<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

final class Reports {
 const METHOD="CASE WHEN EXISTS(SELECT 1 FROM decisions allocation_method WHERE allocation_method.invoice_id=i.id AND allocation_method.action='netopia_allocation' AND allocation_method.active=1) THEN 'NETOPIA' WHEN p.id IS NOT NULL THEN 'NETOPIA' WHEN COALESCE(s.awb,'')='' AND COALESCE(o.awb,'')='' THEN 'GPD' WHEN pref.payment_method IS NOT NULL THEN pref.payment_method WHEN s.service_type='STANDARD' AND (s.cash_due_cents=0 OR s.cash_due_cents IS NULL) THEN 'NETOPIA' WHEN s.cash_due_cents>0 AND s.service_type IN ('STANDARD','CONT COLECTOR') THEN 'FAN' WHEN o.payment_method='Plata online - NETOPIA Payments' THEN 'NETOPIA' WHEN o.payment_method='Plata in sistem ramburs' AND o.awb IS NOT NULL THEN 'FAN' ELSE '' END";
 const ACCEPTED="COALESCE((SELECT reviewed.accepted_difference_cents FROM decisions reviewed WHERE reviewed.invoice_id=i.id AND reviewed.payment_id=p.id AND reviewed.action='source_reviewed' AND reviewed.active=1 AND JSON_UNQUOTE(JSON_EXTRACT(reviewed.source_hashes_json,'$.invoice_hash'))=i.source_hash AND JSON_UNQUOTE(JSON_EXTRACT(reviewed.source_hashes_json,'$.payment_hash'))=p.source_hash ORDER BY reviewed.id DESC LIMIT 1),pd.accepted_difference_cents)";
 static function reviewSQL():string{return "(i.scope_reason='retained' OR EXISTS(SELECT 1 FROM decisions changes WHERE changes.invoice_id=i.id AND changes.action='source_changed' AND changes.active=1) OR (p.id IS NOT NULL AND p.gross_amount_cents-i.amount_cents NOT IN(0,1) AND p.gross_amount_cents-i.amount_cents<>COALESCE(".self::ACCEPTED.",p.gross_amount_cents-i.amount_cents+1)))";}
 const JOINS=' FROM invoices i LEFT JOIN shipment_assignments sa ON sa.invoice_id=i.id AND sa.primary_slot=1 LEFT JOIN fan_shipments s ON s.id=sa.shipment_id LEFT JOIN payment_resolutions pr ON pr.invoice_id=i.id LEFT JOIN netopia_payments p ON p.id=pr.payment_id LEFT JOIN decisions pd ON pd.id=pr.decision_id LEFT JOIN invoice_orders io ON io.invoice_id=i.id LEFT JOIN site_orders o ON o.id=io.order_id LEFT JOIN invoice_preferences pref ON pref.invoice_id=i.id LEFT JOIN gpd_deliveries gd ON (gd.invoice_id=i.id OR (gd.invoice_id IS NULL AND gd.order_id=o.id)) LEFT JOIN gpd_drivers driver ON driver.id=gd.driver_id';
 static function report(\PDO $db,array $filters,bool $all=false):array {
  $mode=$filters['mode']??'active';$where="i.scope<>'internal' AND i.amount_cents>0";$args=[];if($mode==='active')$where.=" AND i.scope='accepted' AND i.balance_cents>0";elseif($mode==='history')$where.=" AND i.scope='accepted' AND i.balance_cents<=0";elseif($mode==='outside')$where.=" AND i.scope='outside'";elseif($mode!=='all')throw new Problem('Filtru invalid.');
  $status=$filters['status']??'';if($status==='review')$where.=' AND '.self::reviewSQL();elseif($status==='waiting')$where.=" AND p.transfer_date IS NULL AND (s.transfer_date IS NULL OR s.delivery_status='returned' OR COALESCE(s.cash_due_cents,0)<=0)";elseif($status==='transferred')$where.=" AND (p.transfer_date IS NOT NULL OR (s.transfer_date IS NOT NULL AND s.delivery_status<>'returned' AND s.cash_due_cents>0) OR ".Allocations::amountSQL('i.id').">0)";elseif($status!=='')throw new Problem('Stare invalidă.');if($status==='waiting')$where.=' AND '.Allocations::amountSQL('i.id').' = 0';
  if(trim($filters['q']??'')!==''){$where.=' AND (LOWER(i.invoice_number) LIKE LOWER(?) OR LOWER(i.client) LIKE LOWER(?) OR LOWER(s.awb) LIKE LOWER(?) OR LOWER(o.order_number) LIKE LOWER(?))';$args=array_fill(0,4,'%'.trim($filters['q']).'%');}if(($filters['method']??'')!==''){$where.=' AND '.self::METHOD.'=?';$args[]=$filters['method'];}foreach(['from'=>'>=','to'=>'<='] as $key=>$op)if(($filters[$key]??'')!==''){if(!validDate($filters[$key]))throw new Problem('Dată filtru invalidă.');$where.=' AND i.invoice_date'.$op.'?';$args[]=$filters[$key];}if(($filters['op']??'')!==''){$where.=' AND LOWER(p.operation_number) LIKE LOWER(?)';$args[]='%'.$filters['op'].'%';}
  $total=one($db,'SELECT COUNT(*) AS total,COALESCE(SUM(i.balance_cents),0) AS balance,COALESCE(SUM(CASE WHEN p.transfer_date IS NOT NULL OR (s.transfer_date IS NOT NULL AND s.delivery_status<>\'returned\' AND s.cash_due_cents>0) THEN COALESCE(p.gross_amount_cents,s.cash_due_cents,0) ELSE 0 END+'.Topups::sumSQL('i.id').'+'.Allocations::amountSQL('i.id').'),0) AS transferred'.self::JOINS.' WHERE '.$where,$args);$page=max(0,(int)($filters['page']??0));$size=50;$select='SELECT i.id,i.invoice_number,i.invoice_date,i.client,i.amount_cents,i.balance_cents,i.scope,i.scope_reason,i.source_hash,EXISTS(SELECT 1 FROM decisions changes WHERE changes.invoice_id=i.id AND changes.action=\'source_changed\' AND changes.active=1) AS pending_changes,s.id AS shipment_id,s.awb,s.awb_date,s.cash_due_cents,s.transfer_date AS fan_transfer,s.delivery_status,s.service_type,p.id AS payment_id,p.source_hash AS payment_hash,p.canonical_external_id AS payment_identifier,p.gross_amount_cents,p.operation_date,p.transfer_date AS netopia_transfer,p.operation_number,p.commission,p.vat,'.self::ACCEPTED.' AS accepted_difference_cents,o.id AS site_id,o.order_number,o.awb AS site_awb,driver.name AS driver,gd.delivery_date,'.self::METHOD.' AS payment_method';$sql=$select.self::JOINS.' WHERE '.$where.' ORDER BY i.invoice_date DESC,i.invoice_number';$sql.=$all?' LIMIT 30000':' LIMIT '.$size.' OFFSET '.($page*$size);$rows=query($db,$sql,$args)->fetchAll();foreach($rows as &$r){$r['delivery_method']=$r['awb']||$r['site_awb']?'FAN':'GPD';$r['delivery_confirmed']=$r['shipment_id']?$r['delivery_status']==='delivered':(bool)$r['delivery_date'];$r['transfer_date']=$r['netopia_transfer']??($r['delivery_status']!=='returned'&&(int)($r['cash_due_cents']??0)>0?$r['fan_transfer']:null);$r['transfer_amount_cents']=$r['transfer_date']?($r['payment_id']?(int)$r['gross_amount_cents']:(int)$r['cash_due_cents']):null;$r['commission_cents']=$r['payment_id']?self::fee($r):null;$difference=$r['payment_id']?(int)$r['gross_amount_cents']-(int)$r['amount_cents']:null;$r['accepted_difference_cents']=$r['accepted_difference_cents']===null?null:(int)$r['accepted_difference_cents'];$r['source_review']=(bool)$r['pending_changes']||$r['scope_reason']==='retained'||($difference!==null&&$difference!==0&&$difference!==($r['accepted_difference_cents']??null)&&$difference!==1);$r['method_declared']=$r['payment_method']==='NETOPIA'&&!$r['payment_id']||$r['payment_method']==='FAN'&&!$r['transfer_date'];Topups::enrich($db,$r);Allocations::enrich($db,$r);}unset($r);return ['rows'=>$rows,'total'=>(int)$total['total'],'balance_cents'=>(int)$total['balance'],'transfer_cents'=>(int)$total['transferred'],'page'=>$page,'page_size'=>$size];
 }
 static function fee(array $r):int{$n=Sources::fixed($r['commission'],5)+Sources::fixed($r['vat'],5);return (int)round($n/1000,0,PHP_ROUND_HALF_UP);}
 static function netopia(\PDO $db,array $f):array {$where='1=1';$args=[];$status=$f['status']??'open';if($status==='open')$where='r.payment_id IS NULL';elseif($status!=='all'){$where='r.resolution=?';$args[]=$status;}if(trim($f['q']??'')!==''){$where.=' AND (LOWER(p.client) LIKE LOWER(?) OR LOWER(p.canonical_external_id) LIKE LOWER(?) OR LOWER(p.operation_number) LIKE LOWER(?) OR EXISTS(SELECT 1 FROM payment_identifiers a WHERE a.payment_id=p.id AND a.external_id LIKE ?))';$args=[...$args,...array_fill(0,4,'%'.trim($f['q']).'%')];}$joins=' FROM netopia_payments p LEFT JOIN '.Topups::links().' r ON r.payment_id=p.id LEFT JOIN invoices i ON i.id=r.invoice_id LEFT JOIN site_orders o ON o.order_number=p.canonical_external_id';$total=(int)query($db,'SELECT COUNT(*)'.$joins.' WHERE '.$where,$args)->fetchColumn();$page=max(0,(int)($f['page']??0));$rows=query($db,'SELECT p.id,p.canonical_external_id,p.client,p.operation_date,p.transfer_date,p.operation_number,p.gross_amount_cents,p.commission,p.vat,p.source_hash,r.resolution,i.invoice_number,o.order_number,o.company,o.amount_cents AS order_amount_cents,COALESCE((SELECT SUM(pp.gross_amount_cents) FROM payment_resolutions rr JOIN netopia_payments pp ON pp.id=rr.payment_id WHERE rr.invoice_id=r.invoice_id),0)+'.Topups::sumSQL('r.invoice_id').' AS invoice_paid_cents'.$joins.' WHERE '.$where.' ORDER BY p.operation_date DESC,p.id LIMIT 50 OFFSET '.($page*50),$args)->fetchAll();foreach($rows as &$r){$r['commission_cents']=self::fee($r);$r['partial_return']=ReturnReview::pending($db,(int)$r['id']);if($r['resolution']==='allocated'){$numbers=query($db,"SELECT i.invoice_number FROM decisions d JOIN invoices i ON i.id=d.invoice_id WHERE d.payment_id=? AND d.action='netopia_allocation' AND d.active=1 ORDER BY i.invoice_number",[$r['id']])->fetchAll(\PDO::FETCH_COLUMN);$r['invoice_number']=implode(' / ',$numbers);}}unset($r);return ['rows'=>$rows,'total'=>$total,'page'=>$page,'page_size'=>50];}
 static function orders(\PDO $db,array $f):array{$joins=' FROM site_orders o LEFT JOIN invoice_orders io ON io.order_id=o.id LEFT JOIN netopia_payments p ON p.canonical_external_id=o.order_number AND p.gross_amount_cents=o.amount_cents LEFT JOIN '.Topups::links().' pr ON pr.payment_id=p.id LEFT JOIN fan_shipments s ON s.awb=o.awb LEFT JOIN shipment_assignments sa ON sa.shipment_id=s.id LEFT JOIN invoices i ON i.id=COALESCE(io.invoice_id,pr.invoice_id,sa.invoice_id)';$where="(i.id IS NULL OR i.scope<>'internal') AND ".SiteFeed::eligibleSQL();$args=[];if(trim($f['q']??'')!==''){$where.=' AND (LOWER(o.order_number) LIKE LOWER(?) OR LOWER(o.client) LIKE LOWER(?) OR LOWER(o.company) LIKE LOWER(?) OR LOWER(o.awb) LIKE LOWER(?))';$args=array_fill(0,4,'%'.trim($f['q']).'%');}if(($f['status']??'open')==='open')$where.=" AND (i.id IS NULL OR i.balance_cents>0) AND COALESCE(pr.resolution,'')<>'allocated'";if(($f['status']??'')==='unlinked')$where.=" AND i.id IS NULL AND COALESCE(pr.resolution,'')<>'allocated'";$page=max(0,(int)($f['page']??0));$total=(int)query($db,'SELECT COUNT(*)'.$joins.' WHERE '.$where,$args)->fetchColumn();$rows=query($db,'SELECT o.*,i.invoice_number,i.balance_cents,pr.resolution,p.id AS payment_id,p.transfer_date,CASE WHEN io.invoice_id IS NULL AND i.id IS NOT NULL THEN 1 ELSE 0 END AS historical_evidence'.$joins.' WHERE '.$where.' ORDER BY o.order_date DESC,o.order_number LIMIT 50 OFFSET '.($page*50),$args)->fetchAll();foreach($rows as &$order)if($order['resolution']==='allocated'){$payment=one($db,'SELECT id FROM netopia_payments WHERE canonical_external_id=?',[$order['order_number']]);$allocated=Allocations::paymentRows($db,(int)$payment['id']);$order['invoice_number']=implode(' / ',array_column($allocated,'invoice_number'));}unset($order);return ['rows'=>$rows,'total'=>$total,'page'=>$page,'page_size'=>50];}
 static function returns(\PDO $db,array $f):array{$rows=query($db,"SELECT s.id,s.awb,s.recipient,s.awb_date,s.order_reference,s.cash_due_cents,s.service_raw,a.invoice_id,i.invoice_number,p.id AS payment_id,p.source_hash AS payment_hash,p.canonical_external_id,p.gross_amount_cents,p.source_hash AS payment_source_hash,s.source_hash AS shipment_source_hash,r.status AS return_status FROM fan_shipments s LEFT JOIN shipment_assignments a ON a.shipment_id=s.id LEFT JOIN invoices i ON i.id=a.invoice_id LEFT JOIN netopia_payments directp ON directp.canonical_external_id=s.order_reference LEFT JOIN payment_resolutions pr ON pr.invoice_id=i.id LEFT JOIN netopia_payments p ON p.id=COALESCE(pr.payment_id,directp.id) LEFT JOIN shipment_returns r ON r.shipment_id=s.id WHERE s.delivery_status='returned' ORDER BY s.awb_date DESC")->fetchAll();$out=[];foreach($rows as $r){$resolved=one($db,"SELECT source_hashes_json FROM decisions WHERE shipment_id=? AND action='return_redelivered' AND active=1 ORDER BY id DESC LIMIT 1",[$r['id']]);$r['redelivery']=$resolved?json_decode($resolved['source_hashes_json'],true):null;$r['method']=method($r);$r['refunds']=query($db,'SELECT refund_amount_cents,refund_date,reference,evidence_type FROM refunds WHERE payment_id=?',[$r['payment_id']??0])->fetchAll();if(($f['method']??'')&&$f['method']!==$r['method'])continue;$out[]=$r;}if(!($f['method']??'')||$f['method']==='NETOPIA')foreach(ReturnReview::rows($db) as $held){$exists=false;foreach($out as $x)if((int)($x['payment_id']??0)===(int)$held['payment_id'])$exists=true;if(!$exists)$out[]=$held;}$status=$f['status']??'open';if(!in_array($status,['open','closed','all'],true))throw new Problem('Stare retur invalidă.');foreach($out as &$row)$row['closed']=ReturnReview::closed($row);unset($row);if($status!=='all')$out=array_values(array_filter($out,fn($row)=>$row['closed']===($status==='closed')));return ['rows'=>$out,'total'=>count($out)];}
 static function attention(\PDO $db):array{return ['aliases'=>query($db,"SELECT a.external_id,a.proof_json,p.id,p.canonical_external_id,p.client,p.gross_amount_cents,p.operation_date,p.source_hash FROM payment_identifiers a JOIN netopia_payments p ON p.id=a.payment_id WHERE a.status='pending'")->fetchAll(),'unclassified_invoices'=>(int)query($db,"SELECT COUNT(*) FROM invoices WHERE scope='outside' AND amount_cents>0")->fetchColumn(),'legacy_drafts'=>(int)query($db,"SELECT COUNT(*) FROM review_batches WHERE status='legacy_draft'")->fetchColumn()];}
 static function exportRows(\PDO $db,array $f,bool $excel=false):array{$data=self::report($db,$f,true);if($data['total']>30000)throw new Problem('Exportul depășește 30.000 de facturi. Restrânge perioada.');return array_map(fn($r)=>[$r['invoice_date'],$r['invoice_number'],$r['client'],(int)$r['amount_cents'],(int)$r['balance_cents'],$r['awb'],$r['transfer_amount_cents'],$r['transfer_date'],$r['operation_number'],$r['payment_method']?:null,$r['commission_cents']],self::exportSelection($data['rows'],$f,$excel));}
 static function textExport(array $rows):string{usort($rows,fn($a,$b)=>strcmp($a[7]??'',$b[7]??'')?:strcmp($a[1],$b[1]));$out="DATA FACTURA\tNR. FACTURA\tCLIENT\tSUMA VIRATA\tDATA VIRAMENT\r\n";$group=null;$sum=0;$has=false;$money=fn($n)=>number_format($n/100,2,',','');foreach($rows as $r){$key=$r[7]??'';if($group!==null&&$key!==$group){$out.='TOTAL VIRAMENT'."\t\t\t".($has?$money($sum):'')."\t".$group."\r\n\r\n";$sum=0;$has=false;}$group=$key;$cells=[$r[0],$r[1],$r[2],$r[6]===null?'':$money($r[6]),$r[7]];$out.=implode("\t",array_map(fn($v)=>str_replace(["\r","\n","\t"],' ',(string)$v),$cells))."\r\n";if($r[6]!==null){$sum+=$r[6];$has=true;}}if($group!==null)$out.='TOTAL VIRAMENT'."\t\t\t".($has?$money($sum):'')."\t".$group."\r\n";return $out;}
 static function exportSelection(array $rows,array $filters,bool $excel):array{if(!$excel||!in_array($filters['method']??'',['FAN','NETOPIA'],true))return $rows;return array_values(array_filter($rows,fn($r)=>!empty($r['transfer_date'])&&$r['transfer_amount_cents']!==null));}
 static function exportFilename(array $filters,bool $text=false):string{$method=in_array($filters['method']??'',['FAN','NETOPIA','GPD'],true)?$filters['method']:'TOATE';$today=(new \DateTimeImmutable('now',new \DateTimeZone('Europe/Bucharest')))->format('Y-m-d');return 'Raport_PLATI_'.$today.'_'.$method.($text?'.txt':'.xlsx');}
 static function xlsx(array $rows):string{$temp=tempnam(sys_get_temp_dir(),'plati_');$z=new \ZipArchive();$z->open($temp,\ZipArchive::OVERWRITE);$xml=fn($v)=>htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');$z->addFromString('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');$z->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Raport" sheetId="1" r:id="rId1"/></sheets></workbook>');$z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');$z->addFromString('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="dd-mm-yy"/></numFmts><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="4"><xf xfId="0"/><xf xfId="0" numFmtId="4" applyNumberFormat="1"/><xf xfId="0" numFmtId="164" applyNumberFormat="1"/><xf xfId="0" numFmtId="1" applyNumberFormat="1"/></cellXfs></styleSheet>');$headers=['DATA FACTURA','NR. FACTURA','CLIENT','VALOARE','REST DE INCASAT','AWB','SUMA VIRATA','DATA VIRAMENT','NR. OP.','PLATA PRIN','COMISION'];$body='';foreach([$headers,...$rows] as $ri=>$row){$body.='<row r="'.($ri+1).'">';foreach($row as $ci=>$value){if($value===null||$value==='')continue;$ref=chr(65+$ci).($ri+1);$style=0;$numeric=false;if($ri>0&&in_array($ci,[3,4,6,10],true)){$value=(int)$value/100;$style=1;$numeric=true;}elseif($ri>0&&in_array($ci,[0,7],true)){$value=(int)(new \DateTimeImmutable('1899-12-30'))->diff(new \DateTimeImmutable($value))->format('%a');$style=2;$numeric=true;}elseif($ri>0&&$ci===5&&ctype_digit((string)$value)&&strlen((string)$value)<=15){$numeric=true;$style=3;}$body.=$numeric?'<c r="'.$ref.'" s="'.$style.'"><v>'.$value.'</v></c>':'<c r="'.$ref.'" t="inlineStr"><is><t xml:space="preserve">'.$xml($value).'</t></is></c>';}$body.='</row>';}$z->addFromString('xl/worksheets/sheet1.xml','<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="11" width="20" customWidth="1"/><col min="3" max="3" width="48" customWidth="1"/></cols><sheetData>'.$body.'</sheetData><autoFilter ref="A1:K'.(count($rows)+1).'"/></worksheet>');$z->close();$result=file_get_contents($temp);unlink($temp);return $result;}
}
